-- 御荷鉾スーパー林道（mikabo-super）の区間データ。tools/road.py build data/roads/mikabo-super.json で生成。手で編集しない。
-- schema.sql を実行したあとに、SQL Editor で全文を実行する。何度実行しても同じ状態になる。
-- 出典：線：© OpenStreetMap contributors（ODbL）
-- 出典：通行可否：上野村「通行止めのお知らせ（令和8年9月2日現在）」で通行止めなし
-- 出典：冬季閉鎖：神流町「冬季通行止め情報」（令和7年度の期間）、藤岡市「御荷鉾スーパー林道冬季閉鎖のお知らせ」（12月10日〜4月20日）
-- 出典：管理者：複数の市町村にまたがるため、沿線市町村としてまとめて登録

set search_path = public, extensions;

insert into administrators (name, kind) values ('御荷鉾スーパー林道 沿線市町村', '市町村')
on conflict (name) do nothing;
insert into roads (name, kind) values ('御荷鉾スーパー林道', '林道')
on conflict (name) do nothing;

delete from segments where road_id = (select id from roads where name = '御荷鉾スーパー林道');

