-- 規制：西端（南牧村側）〜神流町付近。OSMの線が途切れている東側（藤岡市側）約16kmは未収録
insert into restrictions (segment_id, kind, reason, starts_on, ends_on, source_url, fetched_at)
select s.id, '冬季閉鎖', '例年12月10日〜4月20日（藤岡市保美濃山〜南牧村勧能）。今季のお知らせは未掲載のため例年の期間で登録', '2026-12-10', '2027-04-20',
  'https://www.town.kanna.gunma.jp/soshiki/sangyokensetsuka/3/4/1169.html', '2026-10-12 11:00+09'
from segments s join roads r on r.id = s.road_id
where r.name = '御荷鉾スーパー林道' and s.note = '西端（南牧村側）〜神流町付近。OSMの線が途切れている東側（藤岡市側）約16kmは未収録';

-- 確認：この林道の区間と規制の数
select s.note as 区間, count(x.id) as 規制数
from segments s join roads r on r.id = s.road_id left join restrictions x on x.segment_id = s.id
where r.name = '御荷鉾スーパー林道' group by s.id, s.note order by s.id;
